  assert.equal(r.ok, true);
  assert.deepEqual(addLine(r.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 150 }), { ok: false, error: 'DISCOUNT_INVALID' });
});

test('addLine preserves discountPercent when updating existing line', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5, discountPercent: 10 }],
  });
  assert.equal(r.ok, true);
  const r2 = addLine(r.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[0].qty, 8);
  assert.equal(r2.value.lines[0].discountPercent, 10);
});

